INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8476, 11096, 'tt0382077', NULL, 'Hide and Seek', 'Hide and Seek', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/orY4PX3TNFdCbdVwhKY32UKMvoA.jpg', 'https://image.tmdb.org/t/p/original/4QwtFTo7e8pfh0HCklVng5xun3y.jpg', 'David Callaway tries to piece together his life in the wake of his wife''s suicide and has been left to raise his nine-year-old daughter, Emily on his own. David is at first amused to discover that Emily has created an imaginary friend named ''Charlie'', but it isn''t long before ''Charlie'' develops a sinister and violent side, and as David struggles with his daughter''s growing emotional problems, he comes to the frightening realisation that ''Charlie'' isn''t just a figment of Emily''s imagination.', NULL, NULL, 6.817, 6.348, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
