INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8479, 891699, 'tt15799866', NULL, 'Silent Night', 'Silent Night', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/tlcuhdNMKNGEVpGqBZrAaOOf1A6.jpg', 'https://image.tmdb.org/t/p/original/gg4zZoTggZmpAQ32qIrP5dtnkEZ.jpg', 'A tormented father witnesses his young son die when caught in a gang''s crossfire on Christmas Eve. While recovering from a wound that costs him his voice, he makes vengeance his life''s mission and embarks on a punishing training regimen in order to avenge his son''s death.', NULL, NULL, 7.2957, 6.145, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
