INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8482, 11896, 'tt0094142', NULL, 'Throw Momma from the Train', 'Throw Momma from the Train', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/fwcIsCwTwF8AXNxvNkrZ5dZlGPz.jpg', 'https://image.tmdb.org/t/p/original/eKSbKlvuLKlMkgtGH4cpjeODh2l.jpg', 'Larry Donner, an author with a cruel ex-wife, teaches a writing workshop in which one of his students, Owen, is fed up with his domineering mother. When Owen watches a Hitchcock classic that seems to mirror his own life, he decides to put the movie''s plot into action and offers to kill Larry''s ex-wife, if Larry promises to murder his mom. Before Larry gets a chance to react to the plan, it seems that Owen has already set things in motion.', NULL, NULL, 3.8921, 6.161, 0, 10.03, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
