INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8499, 10555, 'tt0307453', NULL, 'Shark Tale', 'Shark Tale', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/r08DpyPyhXcJTfNZAICNGMzcQ8l.jpg', 'https://image.tmdb.org/t/p/original/7ZmZxar3bYORcl0TPA4oceyxcaE.jpg', 'Oscar is a small fish whose big aspirations often get him into trouble. Meanwhile, Lenny is a great white shark with a surprising secret that no sea creature would guess: He''s a vegetarian. When a lie turns Oscar into an improbable hero and Lenny becomes an outcast, the two form an unlikely friendship.', NULL, NULL, 14.0518, 6.045, 0, 2.03, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8500, 53501, 'tt0329589', NULL, 'Shark Hunter', 'Shark Hunter', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/icdh01ANwR1OP95yWjdzuEWPWCQ.jpg', 'https://image.tmdb.org/t/p/original/1GkkXRWPSB4ru5RwSeZDgIPViIe.jpg', 'The Megalodon shark. A prehistoric killing machine 60 feet long, flashing 200 pounds of teeth and weighing over 20 tons. It''s the deadliest predator the world has ever seen. The scientists say it''s been extinct for more than 10,000 years. The scientists are wrong. In the darkness of the deep, an underwater research station has been viciously destroyed. Now a tough team of daring divers led by Spencer Northcutt [Antonio Sabato Jr. "Melrose Place"] is taking an experimental sub to war. It''s killer instinct vs. sophisticated technology, deadly jaws vs. harpoon-tipped torpedoes, mega-shark vs. modern man is a thrilling extreme deep sea fight to the death.', NULL, NULL, 0.9796, 4.429, 0, 1.04, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
