INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8502, 46658, 'tt0100273', NULL, 'Night of the Sharks', 'La notte degli squali', 'movie', 1988, 'https://image.tmdb.org/t/p/w500/k7uANw9W3gkcgtJQBgtPX4g7Cah.jpg', 'https://image.tmdb.org/t/p/original/hAqTWPjlRdi2D32M5wl4ucxQ6fo.jpg', 'David must fight for his life against the gangsters who killed his brother for a CD filled with proof of their illegal activities. When David gets possession of the CD they go down to Mexico where David lives as a shark hunter. Who will get David first, the gangsters or the shark?', NULL, NULL, 1.2559, 3.2, 0, 1.04, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
