INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8548, 5289, 'tt0402910', NULL, 'Chaos', 'Chaos', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/fsqOoouBsNo69vbh2WG6PtpzGBa.jpg', 'https://image.tmdb.org/t/p/original/rR8c2J0i8j9tEjacHE8xgEDPDUS.jpg', 'In Seattle, detective Quentin Conners is unfairly suspended and his partner Jason York leaves the police force after a tragic shooting on Pearl Street Bridge, when the hostage and the criminal die. During a bank heist with a hostage situation, Conners is assigned in charge of the operation with the rookie Shane Dekker as his partner. The thieves, lead by Lorenz, apparently do not steal a penny from the bank. While chasing the gangsters, the police team disclose that they planted a virus in the system, stealing one billion dollars from the different accounts, using the principle of the Chaos Theory. Further, they find that Lorenz is killing his accomplices.', NULL, NULL, 6.0312, 6.315, 0, 1.0, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
