INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8550, 39883, 'tt0108053', NULL, 'Schramm', 'Schramm', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/hqBtS1w5yL1S9jjyvdCOnGhfFU7.jpg', 'https://image.tmdb.org/t/p/original/8eeProseSvUSMPr1WNWPuRAp93S.jpg', 'Lothar Schramm is a simple man with complex problems, yet he seems like such a nice guy. He works as a taxi driver and lives by himself where he is happy to answer his door to strangers and kill them outright. As with many shy loner types he has a problem dealing with women so he drugs them and photographs their nude bodies for sexual stimulation. He then murders his helpless victims and so goes the life of a deranged serial killer.', NULL, NULL, 1.3059, 5.824, 0, 1.0, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
