INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8552, 117525, 'tt0271395', NULL, 'Beyond Vanilla', 'Beyond Vanilla', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/qIpIRMUnv5AcDR3Zm5csiYWquzz.jpg', 'https://image.tmdb.org/t/p/original/zJsnK4DsSPbxbAtvqLmwIcBwp7W.jpg', 'Much as the title suggests, Beyond Vanilla explores the kinkier aspects of sex on the other side of vanilla. With interviews, demonstrations and a good dose of how-to instructions, this documentary covers the gamut of fetishes and SM practices. From bondage, flogging and fisting to knife play, fire and golden showers, director Claes Lilja takes us on an unforgettable journey to the wilder side of sex. Sharing fantasies, experiences and pleasures, the over 60 people interviewed in the film help to blur boundaries and shed new light on sexuality and sexual practices. Open your mind and the rest will follow...', NULL, NULL, 1.1871, 4.875, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
