INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8584, 39525, 'tt1703925', NULL, 'Wilfred', 'Wilfred', 'tv', 2011, 'https://image.tmdb.org/t/p/w500/2cUYCkmHEWsxaNiVTQnFqxyq5Ij.jpg', 'https://image.tmdb.org/t/p/original/f43EKMX1QHJhiieDfhRgh5M1fZj.jpg', 'Everyone else sees Wilfred as just a dog, but Ryan sees a crude and somewhat surly, yet irrepressibly brave and honest Australian bloke in a cheap dog suit. While leading him through a series of comedic and existential adventures, Wilfred the dog shows Ryan the man how to overcome his fears and joyfully embrace the unpredictability and insanity of the world around him.', NULL, NULL, 9.2054, 7.535, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
