INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8587, 142026, 'tt0246507', NULL, 'The Dancing Pig', 'Le Cochon Danseur', 'movie', 1907, 'https://image.tmdb.org/t/p/w500/1t3EmYUMFCbqbyt6eRwuZfUkz6z.jpg', 'https://image.tmdb.org/t/p/original/nC1orurB4jVbIVR5siJvqhvVKyM.jpg', 'This short burlesque film presents an anthropomorphic pig in elegant dress flirting and dancing with a woman, before being humiliated and compelled to perform for her amusement. The film is a screen adaptation of "Le cochon mondain," a successful Paris music-hall act, likely performed by its creator Odéo using the same custom-designed costume.', NULL, NULL, 0.8594, 6.198, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8588, 5709, 'tt0092546', NULL, 'Amazon Women on the Moon', 'Amazon Women on the Moon', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/p77UlHHzyBUCKgdbLosrAnltDgw.jpg', 'https://image.tmdb.org/t/p/original/nAl380kw8qxE7FeSdbbghKuUlp6.jpg', 'Centered on a television station which features a 1950s-style sci-fi movie interspersed with a series of wild commercials, wacky shorts and weird specials, this lampoon of contemporary life and pop culture skewers some of the silliest spectacles ever created in the name of entertainment.', NULL, NULL, 3.017, 5.876, 0, 8.02, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8589, 9707, 'tt0281686', NULL, 'Bubba Ho-tep', 'Bubba Ho-tep', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/pKQBit5ZV7GEOTiMBSYC6xBn86K.jpg', 'https://image.tmdb.org/t/p/original/1TpUjiwMYtASIJYbtuyPkCe4kKw.jpg', 'The "true" story of what really became of Elvis Presley. We find Elvis as an elderly resident in an East Texas rest home, who switched identities with an Elvis impersonator years before his "death," then missed his chance to switch back. He must team up with JFK and fight an ancient Egyptian mummy for the souls of their fellow residents.', NULL, NULL, 3.2484, 6.492, 0, 9.11, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8590, 437986, NULL, NULL, 'Colossal Cave', 'Colossal Cave', 'movie', 2016, NULL, 'https://image.tmdb.org/t/p/original/jva7VRSFY1mTDXIgzrHc9jCmZfG.jpg', 'Plato''s allegory of the cave is often read as a prefiguration of cinema. Yet this film illustrates how online gaming was born from a network of caves. The reconstruction of one couple''s hobby, spending all their time in the world''s largest cave system, leads us to the conception of a pioneering video game.', NULL, NULL, 2.0399, 0.0, 0, 9.06, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
