INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8614, 34312, 'tt0096119', NULL, 'Sleepaway Camp III: Teenage Wasteland', 'Sleepaway Camp III: Teenage Wasteland', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/2YQFABNldAEdMVZOjfKUp4Ig4yp.jpg', 'https://image.tmdb.org/t/p/original/8Z0edRCeyfA36d7RV5CDZq13Ajt.jpg', 'Psychotic Angela is itching to do what she does best: slaughter dozens of teenage campers. As luck would have it, the previous site of her murders has been renamed and converted into an experimental summer camp meant to bring together privileged and lower-class teens. On the day the youths are boarding the buses to camp, Angela runs over a potential camper with a garbage truck and assumes her identity. Once she has infiltrated the camp, the real terror begins.', NULL, NULL, 2.1276, 5.4, 0, 10.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8615, NULL, NULL, 194404, 'The Quarry', 'The Quarry', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4kl4.jpg', NULL, 'It''s late summer in the remote forests of upstate New York, and the teen counselors of Hackett''s Quarry have the camp to themselves for one final night. That means no kids, no adults, and no rules. In this thrilling cinematic tale, you control the fates of all nine camp counselors as their party plans unravel into an unpredictable night of horror. With life-or-death decisions around every turn, the choices you make will determine how the story unfolds.', 'https://www.igdb.com/games/the-quarry', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, NULL, 0, 11.565, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
