INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8617, 47957, 'tt0082696', NULL, 'Madman', 'Madman', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/2pZxY7b22LicdcvWNMCyX8VseVG.jpg', 'https://image.tmdb.org/t/p/original/nYLlApF2ucvJJ2p2yxVYg1bOqql.jpg', 'Madman Marz, an old folklore legend who murdered his family before escaping into the woods, is inadvertently summoned to a campsite to finish the spree he started decades ago.', NULL, NULL, 1.523, 5.011, 0, 10.02, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
