INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8620, 31915, 'tt0079758', NULL, 'Prophecy', 'Prophecy', 'movie', 1979, 'https://image.tmdb.org/t/p/w500/8jCyz5IRWmu8R5FhRO2BqtQXnCj.jpg', 'https://image.tmdb.org/t/p/original/i76LnMcUE38uBWM3K1Rol53sk2A.jpg', 'When a dispute occurs between a logging operation and a nearby Native American tribe, Dr. Robert Verne and his wife, Maggie, are sent in to mediate. Chief John Hawks insists the loggers are poisoning the water supply, and, though company man Isley denies it, the Vernes can''t ignore the strangely mutated wildlife roaming the woods. Robert captures a bear cub for testing and soon finds himself the target of an angry mutant grizzly.', NULL, NULL, 2.5683, 5.467, 0, 10.02, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8621, 999243, 'tt21267296', NULL, 'Hell of a Summer', 'Hell of a Summer', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/q9rRLc9pRDR8H6YoJTmXrBmivxD.jpg', 'https://image.tmdb.org/t/p/original/517uHmTS9Z9nUWBe0gcFaoehNk6.jpg', 'When 24-year-old Jason Hochberg arrives for counsellor weekend at his beloved Camp Pineway, his biggest problem is feeling out of touch with his teenage co-workers. Little does he know; a masked killer has murdered camp owners John and Kathy and is preparing to strike again.', NULL, NULL, 4.9824, 5.514, 0, 11.02, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8622, 1134048, 'tt15220066', NULL, 'Marshmallow', 'Marshmallow', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/qZseaOw1BgLkJsfiEmNpS1KhH8d.jpg', 'https://image.tmdb.org/t/p/original/x6p8NZGyQt9dP7RDTLi1IXdqvtC.jpg', 'At a secluded summer camp, timid and introverted 12-year-old Morgan is thrust into a waking nightmare when a once-fabled campfire tale becomes real. As a mysterious figure descends upon the camp, Morgan and his newfound friends must embark on a treacherous journey and uncover a sinister reality buried beneath the surface.', NULL, NULL, 2.7791, 6.089, 0, 8.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8623, 19209, 'tt0094318', NULL, 'White Water Summer', 'White Water Summer', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/jvoxMkXms4O490OlCNuJk4y7ZB4.jpg', 'https://image.tmdb.org/t/p/original/14oCrQ2HQnc3hHi9P7vSgQXsW9J.jpg', 'When the experienced guide Vic accompanies the city boy Alan and his three friends on their first wilderness experience, he not only hopes to teach the four boys lessons about the wilderness, but about themselves. Vic pushes them to the limit. Soon after alienating the boys, Vic finds himself in desperate need of help and must rely on his students in order to survive.', NULL, NULL, 2.4196, 6.12, 0, 7.03, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
