INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8628, 266880, 'tt3661072', NULL, 'Giuseppe Makes a Movie', 'Giuseppe Makes a Movie', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/84wEpo82TdGQV8yO7bv1yNw3wtf.jpg', 'https://image.tmdb.org/t/p/original/aJYPRoBlv2dRjFGWyA2xxLHXCJd.jpg', 'While the rest of America slept, DIY filmmaker/musician Giuseppe Andrews has made over 30 experimental features. Set in some demented alternate universe (i.e. Ventura, California), they are populated by real-life alcoholics and drug addicts, trash-talking senior citizens and trailer park residents dressed in cow outfits and costume-shop wigs. Director Adam Rifkin creates a wildly surreal, outrageously funny and strangely touching portrait of a truly Outsider Artist inhabiting a world few of us even know exists.', NULL, NULL, 0.6775, 7.8, 0, 1.04, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
