INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8630, 4292, 'tt0103376', NULL, 'Bottom', 'Bottom', 'tv', 1991, 'https://image.tmdb.org/t/p/w500/bOrajiWj3Rax8KZ4ZZWcw2KpJD6.jpg', 'https://image.tmdb.org/t/p/original/hS2xAK3X1oWiaA8OX5Bow2SF6KN.jpg', 'Richie Richard (socially awkward, sexually inexperienced) and Eddie Hitler (carefree alcoholic ) are two social outcasts living on the dole. Trapped together in a squalid flat in Hammersmith, London they are perpetually skint, bored and sexually frustrated. They spend their days scheming, bickering, and being nasty and sadistic to each other.', NULL, NULL, 6.453, 7.923, 0, 1.02, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8631, 81583, 'tt1337139', NULL, '45365', '45365', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/zgKv8FdBPKZKPoCdwJNJjAifiYl.jpg', 'https://image.tmdb.org/t/p/original/be5hThxzE6vHy9H3rSwm9e3t0zO.jpg', 'With cameras in hand, directors Bill and Turner Ross return to their hometown of Sidney, Ohio—zip code 45365—for nine months. In this small town, the stories of a father and son, cops and criminals, officials and their electorate coalesce into a mosaic of faces, places, and events.', NULL, NULL, 0.7941, 6.143, 0, 1.02, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8632, 12706, 'tt0159382', NULL, 'Croupier', 'Croupier', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/bLLa74hdq9qsJpcVqLSwm3fKzJn.jpg', 'https://image.tmdb.org/t/p/original/maKFO957CHUHZ9K34Hqtg1oMojH.jpg', 'Jack Manfred is an aspiring writer who to make ends meet, takes a job as a croupier. Jack remains an observer, knowing that everything in life is a gamble and that gamblers are born to lose. Inevitably, he gets sucked into the world of the casino which takes its toll on his relationships and the novel he is writing.', NULL, NULL, 3.3581, 6.733, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
