INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8636, 916945, 'tt25811680', NULL, 'The Nutcracker and the Mouse King', 'The Nutcracker and the Mouse King', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/r46rBvkRFh5SkghW77DANRN7kIE.jpg', NULL, 'Conceived by John Mauceri, this new work is a re-imagination of Tchaikovsky’s holiday favorite, "The Nutcracker." Based on E.T.A. Hoffmann’s 1816 book, Alan Cumming recounts the origin story of how a prince got put into a nutcracker. Unlike the ballet, we also learn what happens when the young girl grows up, having saved the prince, and what they are doing today.', NULL, NULL, 0.9441, 0.0, 0, 1.06, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8637, 4523, 'tt0461770', NULL, 'Enchanted', 'Enchanted', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/8KCNzCArLlvLdQoHx6npua2VSVc.jpg', 'https://image.tmdb.org/t/p/original/u4UpRDi0w84aNrigr9p049rMHiy.jpg', 'The beautiful princess Giselle is banished by an evil queen from her magical, musical animated land and finds herself in the gritty reality of the streets of modern-day Manhattan. Shocked by this strange new environment that doesn''t operate on a "happily ever after" basis, Giselle is now adrift in a chaotic world badly in need of enchantment. But when Giselle begins to fall in love with a charmingly flawed divorce lawyer who has come to her aid - even though she is already promised to a perfect fairy tale prince back home - she has to wonder: Can a storybook view of romance survive in the real world?', NULL, NULL, 11.3809, 6.847, 0, 1.11, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
