INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8652, 333484, 'tt2404435', NULL, 'The Magnificent Seven', 'The Magnificent Seven', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/ezcS78TIjgr85pVdaPDd2rSPVNs.jpg', 'https://image.tmdb.org/t/p/original/4qxZJRYe4ezA5J1sidnV7vuaYaz.jpg', 'Looking to mine for gold, greedy industrialist Bartholomew Bogue seizes control of the Old West town of Rose Creek. With their lives in jeopardy, Emma Cullen and other desperate residents turn to bounty hunter Sam Chisolm for help. Chisolm recruits an eclectic group of gunslingers to take on Bogue and his ruthless henchmen. With a deadly showdown on the horizon, the seven mercenaries soon find themselves fighting for more than just money once the bullets start to fly.', NULL, NULL, 12.1706, 6.496, 0, 7.02, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
