INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8690, 31589, 'tt0054460', NULL, 'The Bad Sleep Well', '悪い奴ほどよく眠る', 'movie', 1960, 'https://image.tmdb.org/t/p/w500/z0LhZ121uaqa31RUeu1mOnaFb5w.jpg', 'https://image.tmdb.org/t/p/original/m9NzvzYugcjkkZ5A3WdQhI3Mbe7.jpg', 'In this loose adaptation of "Hamlet," illegitimate son Kôichi Nishi climbs to a high position within a Japanese corporation and marries the crippled daughter of company vice president Iwabuchi. At the reception, the wedding cake is a replica of their corporate headquarters, but an aspect of the design reminds the party of the hushed-up death of Nishi''s father. It is then that Nishi unleashes his plan to avenge his father''s death.', NULL, NULL, 2.5089, 7.715, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8691, 69342, 'tt0101660', NULL, 'The Dark Backward', 'The Dark Backward', 'movie', 1991, 'https://image.tmdb.org/t/p/w500/18jN1J9lwGeKFTVzfz2DJ9gGmky.jpg', 'https://image.tmdb.org/t/p/original/qAqFfB9J4QY6yxjfl7SiX7FXBwV.jpg', 'A man pursues stand-up comedy encouraged by his fellow garbage man. Though his friend, who accompanies him on accordion, continues to tell him how great he is, he actually stinks. When the "comedian" grows a third arm out of his back, the friend uses this twist to get him signed up with a sleazy talent agent, and it begins to look like his career is on the move, even though his girlfriend has left him.', NULL, NULL, 1.7675, 5.7, 0, 1.02, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8692, NULL, NULL, 2155, 'Dark Souls', 'Dark Souls', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1x78.jpg', NULL, 'Dark Souls is an action role-playing game developed by FromSoftware and published by Bandai Namco Entertainment. Released in September 2011 as a spiritual sequel to Demon''s Souls, it is set in a dark, medieval fantasy world. It is renowned for its challenging gameplay, intricate level design, and deep lore. Players control a customizable character known as the Chosen Undead, embarking on a perilous journey to uncover the secrets of the cursed land of Lordran.

Dark Souls is known for its punishing difficulty, requiring players to carefully manage combat, stamina, and resources while navigating hostile environments filled with dangerous enemies and formidable bosses. The game features a unique multiplayer component, allowing players to leave messages for others, summon allies for cooperative play, or invade other players'' worlds for PvP combat.

The original release of Dark Souls received critical acclaim for its atmospheric world, innovative mechanics, and rewarding gameplay, solidifying its place as a seminal title in the action RPG genre.', 'https://www.igdb.com/games/dark-souls', '["PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "Xbox 360", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 2.025, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8693, NULL, NULL, 119171, 'Baldur''s Gate III', 'Baldur''s Gate III', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co670h.jpg', NULL, 'An ancient evil has returned to Baldur''s Gate, intent on devouring it from the inside out. The fate of Faerun lies in your hands. Alone, you may resist. But together, you can overcome.', 'https://www.igdb.com/games/baldurs-gate-iii', '["Google Stadia", "Xbox Series X|S", "Linux", "PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, NULL, 0, 1.05, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8694, NULL, NULL, 1134, 'Castlevania: Aria of Sorrow', 'Castlevania: Aria of Sorrow', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob947.jpg', NULL, 'The year is 2035 and Soma Cruz is about to witness the first solar eclipse of the 21st century when he suddenly blacks out -- only to awaken inside a mysterious castle. As Soma, you must navigate the castle''s labyrinths while confronting perilous monsters at every turn. But beware, you must escape before the evil consumes you!', 'https://www.igdb.com/games/castlevania-aria-of-sorrow', '["Wii U", "Game Boy Advance"]', NULL, NULL, 0, 3.085, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
