INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8696, NULL, NULL, 500, 'Batman: Arkham Asylum', 'Batman: Arkham Asylum', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1voj.jpg', NULL, 'Batman: Arkham Asylum is an action-adventure game developed by Rocksteady Studios and published by Warner Bros. Interactive Entertainment. Released in 2009, it follows Batman as he battles the Joker, who seizes control of Arkham Asylum and frees its inmates. The game features stealth, combat, and detective elements, with players using Batman''s gadgets and skills to subdue enemies and solve puzzles.

Set in a dark, immersive version of Gotham, the story explores Batman’s psychological battle with his foes, including Harley Quinn, Bane, and Scarecrow. The game received critical acclaim for its gameplay, atmosphere, and storytelling, becoming a defining title in superhero video games.', 'https://www.igdb.com/games/batman-arkham-asylum', '["PlayStation 3", "Ouya", "PC (Microsoft Windows)", "Mac", "Xbox 360", "Nintendo Switch"]', NULL, NULL, 0, 1.04, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8697, NULL, NULL, 3, 'Thief: Deadly Shadows', 'Thief: Deadly Shadows', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2rom.jpg', NULL, 'In the third instalment of the Thief series, master-thief Garrett is contacted by Keeper Artemus with a mission to steal two valuable artefacts. At the same time, Garrett learns about a prophecy: the coming of a Dark Age. He embarks upon a journey to unravel a mystery that threatens the existence of the order of Keepers. Is it possible that there is a traitor in their midst?

The stealth and thievery game, Thief: Deadly Shadows comes with a number of improvements over two previous parts. Released in 2004, it left behind the aging Dark Engine, using a heavily modified Unreal engine instead. Realistic lighting effects have been implemented: each character and object now casts its own shadow. A third person''s view has been made available in addition to the standard first person perspective.

The stealth system that made Thief: The Dark Project and Thief 2: The Metal Age famous is still in place. You have to stick to the shadows and avoid making noise, as guards will react to anything suspicious. It is also the first game of the series that introduced free roaming. The City, divided into several unlockable districts, is yours to explore. You can interact with the city''s inhabitants: pickpocket, steal, or even mug them for loot.', 'https://www.igdb.com/games/thief-deadly-shadows', '["Xbox", "PC (Microsoft Windows)"]', NULL, NULL, 0, 1.05, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8698, NULL, NULL, 204460, 'The Lord of the Rings: Return to Moria', 'The Lord of the Rings: Return to Moria', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7a7g.jpg', NULL, 'The only survival crafting game set in the Fourth Age of Middle-earth, the iconic fantasy world created by J.R.R. Tolkien.', 'https://www.igdb.com/games/the-lord-of-the-rings-return-to-moria', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 2.045, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8699, NULL, NULL, 133896, 'The Last Faith', 'The Last Faith', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co76ub.jpg', NULL, 'The Last Faith is an exploration-based Metroidvania, action side-scrolling platformer with dark and gothic horror themes at its core. An ancient religion is ruling for centuries the world left to its fate. The once majestic capital and full of a glorious past, is now decadent and haunted by a fatal disease. Eric will have to subvert the words of the hidden prophecy and discover the truth behind the now corrupted and ravaged world.', 'https://www.igdb.com/games/the-last-faith', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 1.0, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8700, 70512, 'tt0002130', NULL, 'Dante''s Inferno', 'L’Inferno', 'movie', 1911, 'https://image.tmdb.org/t/p/w500/ky0z9hDlajlwL3fBqwsCSbjJGjR.jpg', 'https://image.tmdb.org/t/p/original/jEk1QNc9fBnbboh9t3nooPoIxBm.jpg', 'The classic tale of Dante''s journey through hell, loosely adapted from the Divine Comedy and inspired by the illustrations of Gustav Doré.  This historically important film stands as the first feature from Italy and the oldest fully-surviving feature in the world, and boasts beautiful sets and special effects that stand above other cinema of the era.', NULL, NULL, 3.435, 6.6, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8701, 2153, 'tt0077474', NULL, 'The Driver', 'The Driver', 'movie', 1978, 'https://image.tmdb.org/t/p/w500/zSpk2OH4MCgLGB06XDv4YUfBTv6.jpg', 'https://image.tmdb.org/t/p/original/qJiaKFJ25vElTeDgxOyU7QU5nGZ.jpg', 'The Driver specializes in driving getaway cars for robberies. His exceptional talent has prevented him from being caught yet. After another successful flight from the police a self-assured detective makes it his primary goal to catch the Driver. He promises pardons to a gang if they help to convict him in a set-up robbery. The Driver seeks help from The Player to mislead the detective.', NULL, NULL, 5.7294, 7.184, 0, 5.034, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8702, 11702, 'tt0120008', NULL, 'The Replacement Killers', 'The Replacement Killers', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/6q96xjyGTQllKAKgmwyBsk5JSe5.jpg', 'https://image.tmdb.org/t/p/original/yYY0eWwfbvb1OTUx5cMNvHogDvs.jpg', 'Hired assassin John Lee is asked by Chinatown crime boss Terence Wei to murder the young son of policeman Stan Zedkov. Lee has the boy in his sights, but his conscience gets the better of him, and he spares the child''s life. Afraid that Wei will take revenge on his family in China, Lee seeks out expert forger Meg Coburn to obtain the passport he needs to get out of the country, but a band of replacement killers is soon on his trail.', NULL, NULL, 4.9913, 6.292, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8703, 1058, 'tt0085276', NULL, 'Breathless', 'Breathless', 'movie', 1983, 'https://image.tmdb.org/t/p/w500/ipnsEbOsnQYO0HMrHTyqsO5osUV.jpg', 'https://image.tmdb.org/t/p/original/xdCPiNCC9ERbc7XJ6z26cRyT9pq.jpg', 'Jesse, a small-time criminal, high-tails it to Los Angeles to rendezvous with a French exchange student. Stealing a car and accidentally killing a highway patrolman, he becomes the most wanted fugitive in L.A.', NULL, NULL, 3.3543, 5.866, 0, 1.02, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
