INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8723, 11940, 'tt0076716', NULL, 'Sinbad and the Eye of the Tiger', 'Sinbad and the Eye of the Tiger', 'movie', 1977, 'https://image.tmdb.org/t/p/w500/kMP5bg26ac1FmNCamOC5WZece6N.jpg', 'https://image.tmdb.org/t/p/original/bJpDvcc2um0g2EA1vr8XlXHgkFk.jpg', 'Princess Farah refuses to marry Sinbad until Prince Kassim, her brother, is able to give his consent. However, the Prince''s wicked stepmother, Queen Zenobia, has changed Kassim into a baboon in order to have her own son crowned as caliph. Sinbad, his crew, the Princess and the transformed Prince travel to a distant land, fighting every obstacle Zenobia places in their path, to seek the advice of a legendary wise man who can possibly tell how to end the spell.', NULL, NULL, 3.305, 6.576, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8724, 42821, 'tt0857297', NULL, 'Welcome to the N-H-K', 'NHKにようこそ！', 'tv', 2006, 'https://image.tmdb.org/t/p/w500/hIsRcWso57zxD2MWBSqze5G4NDS.jpg', 'https://image.tmdb.org/t/p/original/5jtc5va1gDiRi9pjnGqgCN1W0hF.jpg', 'Sato is a tangle of anxieties and conspiracy theories, believing that the nefarious N-H-K wants to turn society’s misfits into a mob of hopeless recluses. Mysterious Misaki might be able to help Sato overcome his phobias—if she can pull him out of his existential foxhole and get him to face the world.', NULL, NULL, 8.987, 8.3, 0, 2.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8725, 6936, 'tt0953318', NULL, 'Ben X', 'Ben X', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/azxAJ9DlfhpvlKd6jSP3cLqOM99.jpg', 'https://image.tmdb.org/t/p/original/9Ce5KKinhLiQl9Hh3pLAWhTOMNZ.jpg', 'Harassed by bullies because of his mild autism, teen Ben finds refuge in an online computer game, which leads him to his virtual dream girl, Scarlite. Together, the odd couple seeks revenge against Ben''s tormentors.', NULL, NULL, 1.5918, 6.958, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
