INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8727, 9825, 'tt0139414', NULL, 'Lake Placid', 'Lake Placid', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/pEszakCP8j9E9S0UPLfEa3Cad3O.jpg', 'https://image.tmdb.org/t/p/original/vvXc5WOBJQa3igNffSxMsqYyoqy.jpg', 'When a man is eaten alive by an unknown creature, the local Game Warden teams up with a paleontologist from New York to find the beast. Add to the mix an eccentric philanthropist with a penchant for "Crocs", and here we go! This quiet, remote lake is suddenly the focus of an intense search for a crocodile with a taste for live animals...and people!', NULL, NULL, 7.0908, 5.937, 0, 11.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8728, 14658, 'tt0239195', NULL, 'Survivor', 'Survivor', 'tv', 2000, 'https://image.tmdb.org/t/p/w500/1usR1nanbDvnc0LJlWd5TOylT9M.jpg', 'https://image.tmdb.org/t/p/original/4WdtTK5SbeXsYeloXHI2WTpgvdE.jpg', 'A reality show contest where sixteen or more castaways split between two or more “Tribes” are taken to a remote isolated location and are forced to live off the land with meager supplies for roughly 39 days. Frequent physical challenges are used to pit the tribes against each other for rewards, such as food or luxuries, or for “Immunity”, forcing the other tribe to attend “Tribal Council”, where they must vote off one of their players.', NULL, NULL, 62.235, 7.3, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8729, 31004, 'tt0097880', NULL, 'The Mighty Quinn', 'The Mighty Quinn', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/4slxiAx6kBl7h80df2xOobWRUTZ.jpg', 'https://image.tmdb.org/t/p/original/qccvASmkC7b9uCrEeTVGTkEbdjH.jpg', 'Police chief Xavier Quinn investigates the gruesome murder of Donald Pater, one of the wealthiest residents on a Caribbean island. He was found decapitated in his Jacuzzi. Although the local political establishment, especially crooked Governor Chalk, insists that small-time thief Maubee is responsible, Xavier has his doubts. This view is complicated by the police chief''s personal history with Maubee: The men have been friends since childhood.', NULL, NULL, 2.176, 6.048, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
