INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8731, 1639, 'tt0120179', NULL, 'Speed 2: Cruise Control', 'Speed 2: Cruise Control', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/gnK1ocpwUTj24zAktzomOJsD2bu.jpg', 'https://image.tmdb.org/t/p/original/wmwEjQpqNXEIadsQoqWUS1pVVBi.jpg', 'A disgruntled former employee hijacks the Seabourn Legend cruise liner. Set on a fixed course, without any means of communication and at the mercy of the hijacker, it''s up to the one cop on vacation, and his soon to be fiancé (hopefully) Annie, to regain control of it before it kills the passengers and causes an environmental disaster. Insurmountable and daunting tasks await them on their  perilous journey throughout the ship trying to fend off the hijacker and save the passengers.', NULL, NULL, 6.8935, 4.6, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
