INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8750, 11532, 'tt0089087', NULL, 'The Emerald Forest', 'The Emerald Forest', 'movie', 1985, 'https://image.tmdb.org/t/p/w500/fdRlqPnPFaPyQqS3KiBLJwWQPBe.jpg', 'https://image.tmdb.org/t/p/original/8JH97RT7J2zMRDx3ia7wwywkIwV.jpg', 'For ten years, engineer Bill Markham has searched tirelessly for his son Tommy who disappeared from the edge of the Brazilian rainforest. Miraculously, he finds the boy living among the reclusive Amazon tribe who adopted him. And that''s when Bill''s adventure truly begins. For his son is now a grown tribesman who moves skillfully through this beautiful-but-dangerous terrain, fearful only of those who would exploit it. And as Bill attempts to "rescue" him from the savagery of the untamed jungle, Tommy challenges Bill''s idea of true civilization and his notions about who needs rescuing.', NULL, NULL, 4.3836, 6.603, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
