INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8758, 79363, 'tt0047976', NULL, 'Dementia', 'Dementia', 'movie', 1955, 'https://image.tmdb.org/t/p/w500/u0dai8tk4urRAox8rZTEXixURUw.jpg', 'https://image.tmdb.org/t/p/original/vnqZ4MsJxaot0lMQ4cXopiFf8de.jpg', 'In a shadowy world stitched from nightmares, a young woman''s harrowing journey in a seedy hotel unveils her traumatic past. Haunted by violence and stalked through desolate streets, her psyche unravels as she confronts an abusive husband and unsettling memories.', NULL, NULL, 1.375, 6.765, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8759, 16047, 'tt0078560', NULL, 'Anne of Green Gables', '赤毛のアン', 'tv', 1979, 'https://image.tmdb.org/t/p/w500/mxAkN3hatitAojYaaFZxnyg4VHJ.jpg', 'https://image.tmdb.org/t/p/original/BDFyz4VH7E4AS5Fy8m9s1mRMcR.jpg', 'Anne Shirley is a freckle-faced, red-haired girl, who grows up in an orphanage having lost her parents at a very early age. Anne is always cheerful and fun-loving despite being brought up without love or affection. When she turns 11, she is adopted by the old farmer Matthew Cuthbert and his sister Marilla. Anne starts her new life at Green Gables, but actually the Cuthberts wanted a boy who could help with their work on the farm...', NULL, NULL, 11.6115, 7.5, 0, 12.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8760, 18989, 'tt0117071', NULL, 'Moll Flanders', 'Moll Flanders', 'movie', 1996, 'https://image.tmdb.org/t/p/w500/lHVpzsvjLU7qSCB8UWFqIAavSRu.jpg', 'https://image.tmdb.org/t/p/original/m6Si2vwNCorETZape82t6iuxTj3.jpg', 'The daughter of a thief, young Moll is placed in the care of a nunnery after the execution of her mother. However, the actions of an abusive priest lead Moll to rebel as a teenager, escaping to the dangerous streets of London. Further misfortunes drive her to accept a job as a prostitute from the conniving Mrs. Allworthy. It is there that Moll first meets Hibble, who is working as Allworthy''s servant but takes a special interest in the young woman''s well-being. With his help, she retains hope for the future, ultimately falling in love with an unconventional artist who promises the possibility of romantic happiness.', NULL, NULL, 2.8961, 6.102, 0, 11.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
