INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8763, 820525, 'tt15334488', NULL, 'After Everything', 'After Everything', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/uQxjZGU6rxSPSMeAJPJQlmfV3ys.jpg', 'https://image.tmdb.org/t/p/original/fH7kYS9qEOkhFQZc0Dcoa9MFjje.jpg', 'Besieged by writer’s block and the crushing breakup with Tessa, Hardin travels to Portugal in search of a woman he wronged in the past – and to find himself. Hoping to win back Tessa, he realizes he needs to change his ways before he can make the ultimate commitment.', NULL, NULL, 10.1167, 6.9, 0, 9.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8764, 866, 'tt0308644', NULL, 'Finding Neverland', 'Finding Neverland', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/A9jgLICNCEb3lvWdNaIKAG9pRdp.jpg', 'https://image.tmdb.org/t/p/original/ursbJ6xP9YnmtlTFKf77KPxmw7U.jpg', 'During a writing slump, playwright J.M. Barrie meets a widow and her four children, all young boys—who soon become an important part of Barrie’s life and the inspiration that lead him to create his masterpiece. Peter Pan.', NULL, NULL, 6.1451, 7.318, 0, 11.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
