INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8768, 228505, 'tt1517190', NULL, 'Hide and Go Kill', 'Hitori kakurenbo', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/8rSThQPKVGGaJjV3oFor0RLAwBB.jpg', NULL, 'A blog on a mysterious website quickly spreads like wildfire, starting a dangerous online game. At 3:00 in the afternoon, a teddy bear stuffed with rice and nails is sunk into a bathtub. The lights go out and the player is required to stab the bear with the knife, then write their experiences in the blog. But lately the comments have taken a dark, demented turn, as if the players are being possessed.', NULL, NULL, 1.5235, 6.0, 0, 10.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8769, NULL, NULL, 8600, 'Fear Effect', 'Fear Effect', 'game', 2000, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8j85.jpg', NULL, 'Fear Effect is an action adventure waiting to unfold! Wee Ming Lam disappears a few days before her 18th birthday under mysterious circumstances. Three ruthless mercenaries conspire to track her down and ransom her off to her father, Mr. Lam, a powerful Triad leader in Hong Kong. An extortion mission to retrieve Wee Ming Lam becomes a lesson in survival against the most unimaginable of enemies.', 'https://www.igdb.com/games/fear-effect', '["PlayStation 3", "PlayStation"]', NULL, NULL, 0, 10.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8770, 42120, 'tt0093435', NULL, 'City on Fire', '龍虎風雲', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/uOgCKhHsQvOFVNxOUdewPwc0Z9N.jpg', 'https://image.tmdb.org/t/p/original/ONKOwS1xCipE5tMr8VsVJySzcH.jpg', 'Ko Chow is an undercover cop who is under pressure from all sides. His boss, Inspector Lau, wants him to infiltrate a gang of ruthless jewel thieves; his girlfriend wants him to commit to marriage or she will leave Hong Kong with another lover; and he is being pursued by other cops who are unaware that he is a colleague. Chow would rather quit the force, feeling guilty about betraying gang members who have become his friends.', NULL, NULL, 4.1066, 6.9, 0, 10.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
