INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8775, NULL, NULL, 1218, 'Shenmue II', 'Shenmue II', 'game', 2001, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2raf.jpg', NULL, 'Yu Suzuki''s cinematic masterpiece returns with more spellbinding adventure and an even more immersive world. The epic continues as Ryo Hazuki arrives in Hong Kong on his quest to avenge his father''s murder by the warlord Lan Di and unravel the mystery of the Phoenix mirror. Set in Hong Kong, Kowloon, and Guilin, you''ll travel through breathtaking scenery, rich with mountainous wilderness, traditional Taoist temples, and stunning tropical landscapes. As you move through massive, highly-detailed 3D worlds, you''ll interact with almost every facet of your environment as well as a whole new cast of characters.

Originally released on Dreamcast in Europe and Japan, this Xbox edition marks the sequel''s debut in the US and includes the Shenmue Movie chronicling the first episode in the series.', 'https://www.igdb.com/games/shenmue-ii', '["Xbox", "PlayStation 4", "Xbox One", "Dreamcast"]', NULL, NULL, 0, 10.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
