INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8795, 20009, 'tt0240900', NULL, 'Slackers', 'Slackers', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/g3xn7tRnGxVwwKc2tge7nPssywQ.jpg', 'https://image.tmdb.org/t/p/original/pmwIaqu40catjSDQTlYSCAHBhzP.jpg', 'Dave, Sam and Jeff are about to graduate from Holden University with honors in lying, cheating and scheming. The three roommates have proudly scammed their way through the last four years of college and now, during final exams, these big-men-on-campus are about to be busted by the most unlikely dude in school. Self-dubbed Cool Ethan, an ambitious nerd with a bad crush, enters their lives one day and everything begins to unravel.', NULL, NULL, 3.0017, 5.198, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8796, 60307, 'tt1650043', NULL, 'Diary of a Wimpy Kid: Rodrick Rules', 'Diary of a Wimpy Kid: Rodrick Rules', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/w77ZoDmHNf6lnk8NWsXqWYOQqnp.jpg', 'https://image.tmdb.org/t/p/original/9BwGL0nsjCdvhe6V9q42NG11Pyq.jpg', 'Wimpy Greg Heffley, now in seventh grade, thinks he has it all together. He has mastered middle school and gotten rid of the Cheese Touch. However, Greg''s older brother, Rodrick, is itching to cut him down to size. He gets the perfect opportunity when their mother tries to force the boys to bond. Rodrick may be Greg''s chief tormentor, but he feels his constant pranks are just what his little brother needs to prepare him for life''s hard knocks.', NULL, NULL, 8.2443, 6.731, 0, 4.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8797, 19286, 'tt0113636', NULL, 'Leprechaun 3', 'Leprechaun 3', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/z9NT2smK66pYOjBtmZuKFFTZ478.jpg', 'https://image.tmdb.org/t/p/original/xGGRgSD7vbkyFwrt24x6cG4ytbp.jpg', 'It was a normal night in Las Vegas, Nevada, all the lights were flashing brightly, until a man with one hand, one eye, and one leg walks into a pawn shop with a statue of a hideous looking Leprechaun. The owner claims it''s a good luck charm. The statue also wore a medallion around it''s neck. The careless pawn shop owner took off the medallion setting the Leprechaun free...', NULL, NULL, 3.8932, 5.824, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
