INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8800, 789243, NULL, NULL, 'The North Shore Brought to Life', 'The North Shore Brought to Life', 'movie', 2007, NULL, NULL, 'Welcome aboard the world''s most famous interurban line, running all the way from Chicago to Milwaukee. Half trolley and half streamlined railroad, this line competed with two other major railroads in intercity traffic for over half a century.', NULL, NULL, 0.3716, 0.0, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (8801, 64688, 'tt1232829', NULL, '21 Jump Street', '21 Jump Street', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/8v3Sqv9UcIUC4ebmpKWROqPBINZ.jpg', 'https://image.tmdb.org/t/p/original/rXrpYOveFl76ivMmyb2612T7Q8w.jpg', 'When cops Schmidt and Jenko join the secret Jump Street unit, they use their youthful appearances to go undercover as high school students. They trade in their guns and badges for backpacks, and set out to shut down a dangerous drug ring. But, as time goes on, Schmidt and Jenko discover that high school is nothing like it was just a few years earlier -- and, what''s more, they must again confront the teenage terror and anxiety they thought they had left behind.', NULL, NULL, 11.7926, 6.884, 0, 1.01, '2026-08-09 02:29:31', '2026-08-09 02:29:31');
