UPDATE "recommendations" SET "tmdb_id"=11020, "imdb_id"='tt0073540', "igdb_id"=NULL, "title"='Picnic at Hanging Rock', "original_title"='Picnic at Hanging Rock', "media_type"='movie', "release_year"=1975, "poster_url"='https://image.tmdb.org/t/p/w500/7BAXwmFN4pZDNb9N6kzmAAwdssi.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/41Mlaj6wfjlF4wQaVH0tjfDXvMi.jpg', "overview"='In the early 1900s, Miranda attends a girls boarding school in Australia. One Valentine''s Day, the school''s typically strict headmistress treats the girls to a picnic field trip to an unusual but scenic volcanic formation called Hanging Rock. Despite rules against it, Miranda and several other girls venture off. It''s not until the end of the day that the faculty realizes the girls and one of the teachers have disappeared mysteriously.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.2583, "vote_average"=7.2, "is_ambiguous"=0, "evidence_score"=3.41479999999999961e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=17;
UPDATE "recommendations" SET "tmdb_id"=16307, "imdb_id"='tt0070917', "igdb_id"=NULL, "title"='The Wicker Man', "original_title"='The Wicker Man', "media_type"='movie', "release_year"=1973, "poster_url"='https://image.tmdb.org/t/p/w500/wwtrXRL8SiOWxhwLEvw7iBgYh0g.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fK5OHX7OIl57UqAbPiM4F3hc9wr.jpg', "overview"='Police sergeant Neil Howie is called to an island village in search of a missing girl whom the locals claim never existed. The investigation is further complicated as Howie’s religious views clash with those of the island’s residents.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.804, "vote_average"=7.333, "is_ambiguous"=0, "evidence_score"=2.35642105263157901e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=18;
UPDATE "recommendations" SET "tmdb_id"=26774, "imdb_id"='tt0066849', "igdb_id"=NULL, "title"='The Blood on Satan''s Claw', "original_title"='The Blood on Satan''s Claw', "media_type"='movie', "release_year"=1971, "poster_url"='https://image.tmdb.org/t/p/w500/shUG4L8iKu9g4bhZVI3SNsIOvD3.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/lVgJzjtd97Aznpbp4KkSM0Oxj7J.jpg', "overview"='After a landsman in 18th century England discovers a corpse covered in fur buried in a field, the town becomes infected by "the devil''s skin," leading the local children to engage in demonic rituals and criminal behavior.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.0181, "vote_average"=6.2, "is_ambiguous"=0, "evidence_score"=10.5375, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=19;
UPDATE "recommendations" SET "tmdb_id"=11905, "imdb_id"='tt0087075', "igdb_id"=NULL, "title"='The Company of Wolves', "original_title"='The Company of Wolves', "media_type"='movie', "release_year"=1984, "poster_url"='https://image.tmdb.org/t/p/w500/2g2YPws1MiEWTodUE8u3qOf78XS.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8LMKwSUdHxU8AGPVY7BV4wS5TeQ.jpg', "overview"='An adaptation of Angela Carter''s fairy tales. Young Rosaleen dreams of a village in the dark woods, where Granny tells her cautionary tales in which innocent maidens are tempted by wolves who are hairy on the inside. As Rosaleen grows into womanhood, will the wolves come for her too?', "external_url"=NULL, "platforms"=NULL, "popularity"=2.6119, "vote_average"=6.3, "is_ambiguous"=0, "evidence_score"=1.78778571428571417e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=20;
UPDATE "recommendations" SET "tmdb_id"=179111, "imdb_id"='tt2375574', "igdb_id"=NULL, "title"='A Field in England', "original_title"='A Field in England', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/dKhMJr8yoHVyvxyUiAeIn2hKVdL.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/euBvKWkvYD38O7dMMvw3GvrkZoa.jpg', "overview"='During the Civil War in 17th-Century England, a small group of deserters flee from a raging battle through an overgrown field. They are captured by an alchemist, who forces the group to aid him in his search to find a hidden treasure that he believes is buried in the field. Crossing a vast mushroom circle, which provides their first meal, the group quickly descend into a chaos of arguments, fighting and paranoia, and, as it becomes clear that the treasure might be something other than gold, they slowly become victim to the terrifying energies trapped inside the field.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.193, "vote_average"=6.212, "is_ambiguous"=0, "evidence_score"=1.46754545454545457e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=21;
UPDATE "recommendations" SET "tmdb_id"=10957, "imdb_id"='tt0088814', "igdb_id"=NULL, "title"='The Black Cauldron', "original_title"='The Black Cauldron', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/h64i9e6oJs2jrDZ4QzspXMqZhPF.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/4idEU92m0oR1BWa1iwb5pZ9bWCu.jpg', "overview"='Taran is an assistant pigkeeper with boyish dreams of becoming a great warrior. However, he has to put the daydreaming aside when his charge, an oracular pig named Hen Wen, is kidnapped by an evil lord known as the Horned King. The villain hopes Hen will show him the way to The Black Cauldron, which has the power to create a giant army of unstoppable soldiers.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.2452, "vote_average"=6.441, "is_ambiguous"=0, "evidence_score"=1.61433333333333344e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=22;
UPDATE "recommendations" SET "tmdb_id"=13597, "imdb_id"='tt0091369', "igdb_id"=NULL, "title"='Labyrinth', "original_title"='Labyrinth', "media_type"='movie', "release_year"=1986, "poster_url"='https://image.tmdb.org/t/p/w500/pejayhTVBEL4w8YKSfrhOjjWVlH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mGkleIuPO2flRyvP8yBcUykSQsp.jpg', "overview"='Frustrated with babysitting on yet another weekend night, Sarah, a teenager with an active imagination, summons the Goblins to take her baby stepbrother away. When little Toby actually disappears, Sarah must follow him into a fantastical world to rescue him from the Goblin King. Guarding his castle is the labyrinth itself, a twisted maze of deception, populated with outrageous characters and unknown dangers.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.6038, "vote_average"=7.289, "is_ambiguous"=0, "evidence_score"=3.00130769230769232e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=23;
