UPDATE "recommendations" SET "tmdb_id"=11236, "imdb_id"='tt0108071', "igdb_id"=NULL, "title"='The Secret Garden', "original_title"='The Secret Garden', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/zf6h5dJ7wVG7LqMO9dhHGHVejzj.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/8s7FJ9dHXgeFZdvxfjPmrrJh6EC.jpg', "overview"='A young British girl born and reared in India loses her neglectful parents in an earthquake. She is returned to England to live at her uncle''s castle. Her uncle is very distant due to the loss of his wife ten years before. Neglected once again, she begins exploring the estate and discovers a garden that has been locked and forgotten. Aided by one of the servants'' boys, she begins restoring the garden, and eventually discovers some other secrets of the manor.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.4349, "vote_average"=7.425, "is_ambiguous"=0, "evidence_score"=24.0795, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=166;
UPDATE "recommendations" SET "tmdb_id"=348, "imdb_id"='tt0078748', "igdb_id"=NULL, "title"='Alien', "original_title"='Alien', "media_type"='movie', "release_year"=1979, "poster_url"='https://image.tmdb.org/t/p/w500/vfrQk5IPloGg1v9Rzbh2Eg3VGyM.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/AmR3JG1VQVxU8TfAvljUhfSFUOx.jpg', "overview"='During its return to the earth, commercial spaceship Nostromo intercepts a distress signal from a distant planet. When a three-member team of the crew discovers a chamber containing thousands of eggs on the planet, a creature inside one of the eggs attacks an explorer. The entire crew is unaware of the impending nightmare set to descend upon them when the alien parasite planted inside its unfortunate host is birthed.', "external_url"=NULL, "platforms"=NULL, "popularity"=22.5272, "vote_average"=8.171, "is_ambiguous"=0, "evidence_score"=3.9985833333333332e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=170;
