UPDATE "recommendations" SET "tmdb_id"=68, "imdb_id"='tt0088846', "igdb_id"=NULL, "title"='Brazil', "original_title"='Brazil', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/aewan59WcFThBimkTVVoNf2o5Vb.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9IYyCLf5NNAQFK9pNtqzEU9HWzM.jpg', "overview"='Low-level bureaucrat Sam Lowry escapes the monotony of his day-to-day life through a recurring daydream of himself as a virtuous hero saving a beautiful damsel. Investigating a case that led to the wrongful arrest and eventual death of an innocent man instead of wanted terrorist Harry Tuttle, he meets the woman from his daydream, and in trying to help her gets caught in a web of mistaken identities, mindless bureaucracy and lies.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.0939, "vote_average"=7.7, "is_ambiguous"=0, "evidence_score"=36.525625, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=535;
UPDATE "recommendations" SET "tmdb_id"=9323, "imdb_id"='tt0113568', "igdb_id"=NULL, "title"='Ghost in the Shell', "original_title"='GHOST IN THE SHELL', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/9gC88zYUBARRSThcG93MvW14sqx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gTRXgigmgKpeJjW07iq686HZyBD.jpg', "overview"='In the year 2029, the barriers of our world have been broken down by the net and by cybernetics, but this brings new vulnerability to humans in the form of brain-hacking. When a highly-wanted hacker known as ''The Puppetmaster'' begins involving them in politics, Section 9, a group of cybernetically enhanced cops, are called in to investigate and stop the Puppetmaster.', "external_url"=NULL, "platforms"=NULL, "popularity"=13.6324, "vote_average"=7.925, "is_ambiguous"=0, "evidence_score"=4.07145714285714248e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=538;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=1877, "title"='Cyberpunk 2077', "original_title"='Cyberpunk 2077', "media_type"='game', "release_year"=2020, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/coaih8.jpg', "backdrop_url"=NULL, "overview"='Cyberpunk 2077 is an open-world action-adventure game set in Night City, a sprawling metropolis driven by power, glamour, and body modification. Players assume the role of V, a mercenary outlaw in pursuit of a unique implant that holds the key to immortality. The game allows extensive customization of cyberware, skills, and playstyle. Choices made throughout the journey influence both the narrative and the world.', "external_url"='https://www.igdb.com/games/cyberpunk-2077', "platforms"='["Google Stadia", "Xbox Series X|S", "PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=6.91, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=542;
