UPDATE "recommendations" SET "tmdb_id"=2291, "imdb_id"='tt0099871', "igdb_id"=NULL, "title"='Jacob''s Ladder', "original_title"='Jacob''s Ladder', "media_type"='movie', "release_year"=1990, "poster_url"='https://image.tmdb.org/t/p/w500/ufLcHIi1aXjjH8MediAMvnwDsVI.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/oubk1SEFtg3Q8eOncFvGQVa6OoP.jpg', "overview"='After returning home from the Vietnam War, veteran Jacob Singer struggles to maintain his sanity. Plagued by hallucinations and flashbacks, Singer rapidly falls apart as the world and people around him morph and twist into disturbing images. His girlfriend, Jezzie, and ex-wife, Sarah, try to help, but to little avail. Even Singer''s chiropractor friend, Louis, fails to reach him as he descends into madness.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.4598, "vote_average"=7.367, "is_ambiguous"=0, "evidence_score"=3.24003448275862098e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=568;
