UPDATE "recommendations" SET "tmdb_id"=5548, "imdb_id"='tt0093870', "igdb_id"=NULL, "title"='RoboCop', "original_title"='RoboCop', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/hHtOgGb3NihlyRATHlKPaFApbrd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/xcaX6BZ1JUPSVMH2gBkWIckLLaA.jpg', "overview"='In a violent, near-apocalyptic Detroit, evil corporation Omni Consumer Products wins a contract from the city government to privatize the police force. To test their crime-eradicating cyborgs, the company leads street cop Alex Murphy into an armed confrontation with crime lord Boddicker so they can use his body to support their untested RoboCop prototype. But when RoboCop learns of the company''s nefarious plans, he turns on his masters.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.3779, "vote_average"=7.364, "is_ambiguous"=0, "evidence_score"=2.10731578947368412e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=777;
UPDATE "recommendations" SET "tmdb_id"=860, "imdb_id"='tt0086567', "igdb_id"=NULL, "title"='WarGames', "original_title"='WarGames', "media_type"='movie', "release_year"=1983, "poster_url"='https://image.tmdb.org/t/p/w500/zZ1rN4LoPxKNfAp67Xl300WxVeD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qtamfYGFfDLfGRcucx1zNwohRts.jpg', "overview"='High school student David Lightman has a talent for hacking. But while trying to hack into a computer system to play unreleased video games, he unwittingly taps into the Department of Defense''s war computer and initiates a confrontation of global proportions. Together with his friend and a wizardly computer genius, David must race against time to outwit his opponent and prevent a nuclear Armageddon.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.5988, "vote_average"=7.068, "is_ambiguous"=0, "evidence_score"=9.01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=778;
UPDATE "recommendations" SET "tmdb_id"=11309, "imdb_id"='tt0099740', "igdb_id"=NULL, "title"='Hardware', "original_title"='Hardware', "media_type"='movie', "release_year"=1990, "poster_url"='https://image.tmdb.org/t/p/w500/ybauOsdo6ColZ1WsALqIYjpUg4X.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nC1qaINaRBY1crPCQoFVPhSrq16.jpg', "overview"='Mark 13 is a government-built killing machine programmed with artificial intelligence, able to repair and recharge itself from any energy source. Through a series of coincidences, the cyborg''s head ends up in the home of a sculptress as a bizarre Christmas present from her boyfriend. Once inside its new home, the cyborg promptly reconstructs the rest of its body using a variety of household utensils and proceeds to go on a murderous rampage.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.4903, "vote_average"=5.922, "is_ambiguous"=0, "evidence_score"=1.21883333333333325e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=782;
UPDATE "recommendations" SET "tmdb_id"=9886, "imdb_id"='tt0113481', "igdb_id"=NULL, "title"='Johnny Mnemonic', "original_title"='Johnny Mnemonic', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/iH8Jgi8qvb7pnBfI8fVGaUbyRna.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7FRYVIF2hnh1IbPtqMgF5iygdjz.jpg', "overview"='In a dystopian 2021, Johnny is a data trafficker who has an implant that allows him to securely store data too sensitive for regular computer networks. On one delivery run, he accepts a package that not only exceeds the implant''s safety limits—and will kill him if the data is not removed in time—but also contains information far more important and valuable than he had ever imagined. On a race against time, he must avoid the assassins sent to kill him and remove the data before it, too, ends his life.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.3516, "vote_average"=5.758, "is_ambiguous"=0, "evidence_score"=16.53, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=785;
UPDATE "recommendations" SET "tmdb_id"=82507, "imdb_id"='tt1922777', "igdb_id"=NULL, "title"='Sinister', "original_title"='Sinister', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nzx10sca3arCeYBAomHan4Q6wa1.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jovIEk4cAxWmA2dBcPrfhn3jzYN.jpg', "overview"='True-crime writer Ellison Oswalt is in a slump; he hasn''t had a best seller in more than 10 years and is becoming increasingly desperate for a hit. So, when he discovers the existence of a snuff film showing the deaths of a family, he vows to solve the mystery. He moves his own family into the victims'' home and gets to work. However, when old film footage and other clues hint at the presence of a supernatural force, Ellison learns that living in the house may be fatal.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.8983, "vote_average"=6.876, "is_ambiguous"=0, "evidence_score"=2.54413636363636364e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=791;
UPDATE "recommendations" SET "tmdb_id"=9479, "imdb_id"='tt0107688', "igdb_id"=NULL, "title"='The Nightmare Before Christmas', "original_title"='The Nightmare Before Christmas', "media_type"='movie', "release_year"=1993, "poster_url"='https://image.tmdb.org/t/p/w500/oQffRNjK8e19rF7xVYEN8ew0j7b.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/dSfrsjhqC6lYe7LYDYnzWeXZmEl.jpg', "overview"='Tired of scaring humans every October 31 with the same old bag of tricks, Jack Skellington, the spindly king of Halloween Town, kidnaps Santa Claus and plans to deliver shrunken heads and other ghoulish gifts to children on Christmas morning. But as Christmas approaches, Jack''s rag-doll girlfriend, Sally, tries to foil his misguided plans.', "external_url"=NULL, "platforms"=NULL, "popularity"=17.5462, "vote_average"=7.833, "is_ambiguous"=0, "evidence_score"=14.20875, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=801;
