UPDATE "recommendations" SET "tmdb_id"=1622, "imdb_id"='tt0460681', "igdb_id"=NULL, "title"='Supernatural', "original_title"='Supernatural', "media_type"='tv', "release_year"=2005, "poster_url"='https://image.tmdb.org/t/p/w500/8iixmfGx5EIFPdpNvB2JvI3VIqX.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ro0tlgnsco4SwbdAgmscLkSlMSL.jpg', "overview"='When they were boys, Sam and Dean Winchester lost their mother to a mysterious and demonic supernatural force. Subsequently, their father raised them to be soldiers. He taught them about the paranormal evil that lives in the dark corners and on the back roads of America ... and he taught them how to kill it. Now, the Winchester brothers crisscross the country in their ''67 Chevy Impala, battling every kind of supernatural threat they encounter along the way. ', "external_url"=NULL, "platforms"=NULL, "popularity"=218.3385, "vote_average"=8.312, "is_ambiguous"=0, "evidence_score"=19.67375, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2180;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=1062, "title"='Alan Wake', "original_title"='Alan Wake', "media_type"='game', "release_year"=2010, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co2dft.jpg', "backdrop_url"=NULL, "overview"='Alan Wake is a psychological horror action-adventure game developed by Remedy Entertainment. The narrative centres on Alan Wake, a bestselling thriller novelist experiencing writer''s block. He travels to the small town of Bright Falls with his wife, Alice, seeking a change of environment. Shortly after their arrival, Alice vanishes under mysterious circumstances.

As Alan searches for her, he discovers pages of a thriller novel he does not recall writing. The events described in these pages begin to manifest in reality, and Alan encounters hostile supernatural entities known as the "Taken," who are controlled by darkness. The gameplay involves navigating Bright Falls and using light to combat these dark forces. The storyline explores themes of reality and fiction, along with the influence of the written word.', "external_url"='https://www.igdb.com/games/alan-wake', "platforms"='["PC (Microsoft Windows)", "Xbox 360"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=1.24514285714285719e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2182;
