UPDATE "recommendations" SET "tmdb_id"=1621, "imdb_id"='tt0979432', "igdb_id"=NULL, "title"='Boardwalk Empire', "original_title"='Boardwalk Empire', "media_type"='tv', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/zyHLWVmqS8m7bxABJjcDFMYLdF8.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7Yj4QbECkH3JavlZxw4NWReoN7B.jpg', "overview"='Atlantic City at the dawn of Prohibition is a place where the rules don''t apply. And the man who runs things -- legally and otherwise -- is the town''s treasurer, Enoch "Nucky" Thompson, who is equal parts politician and gangster.', "external_url"=NULL, "platforms"=NULL, "popularity"=34.7601, "vote_average"=8.02, "is_ambiguous"=0, "evidence_score"=1.13514285714285705e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2353;
UPDATE "recommendations" SET "tmdb_id"=82682, "imdb_id"='tt1321870', "igdb_id"=NULL, "title"='Gangster Squad', "original_title"='Gangster Squad', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/wAuQNTBFBu2yXZsX6yLhUPiwTlW.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cdd4S09XxLLvp6IRN4PQamPAXL6.jpg', "overview"='Los Angeles, 1949. Ruthless, Brooklyn-born mob king Mickey Cohen runs the show in this town, reaping the ill-gotten gains from the drugs, the guns, the prostitutes and — if he has his way — every wire bet placed west of Chicago. And he does it all with the protection of not only his own paid goons, but also the police and the politicians who are under his control. It’s enough to intimidate even the bravest, street-hardened cop… except, perhaps, for the small, secret crew of LAPD outsiders led by Sgt. John O’Mara and Jerry Wooters who come together to try to tear Cohen’s world apart.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.8111, "vote_average"=6.381, "is_ambiguous"=0, "evidence_score"=6.06666666666666643e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2355;
UPDATE "recommendations" SET "tmdb_id"=840430, "imdb_id"='tt14849194', "igdb_id"=NULL, "title"='The Holdovers', "original_title"='The Holdovers', "media_type"='movie', "release_year"=2023, "poster_url"='https://image.tmdb.org/t/p/w500/VHSzNBTwxV8vh7wylo7O9CLdac.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/A99WMiz0ASpH9coOFrxSEuwTWx0.jpg', "overview"='A curmudgeonly instructor at a New England prep school is forced to remain on campus during Christmas break to babysit the handful of students with nowhere to go. Eventually, he forms an unlikely bond with one of them — a damaged, brainy troublemaker — and with the school’s head cook, who has just lost a son in Vietnam.', "external_url"=NULL, "platforms"=NULL, "popularity"=6.9543, "vote_average"=7.646, "is_ambiguous"=0, "evidence_score"=2.00141176470588249e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2373;
UPDATE "recommendations" SET "tmdb_id"=42034, "imdb_id"='tt0089052', "igdb_id"=NULL, "title"='Dreamchild', "original_title"='Dreamchild', "media_type"='movie', "release_year"=1985, "poster_url"='https://image.tmdb.org/t/p/w500/vgmONyJ6Io0sPibW9SRiZFHVOO0.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/6Q5a6x8s4DK94LV4TGsuzqbWlMw.jpg', "overview"='80-year-old Alice Hargreaves is about to visit Columbia University to attend a reception in honour of author Lewis Carroll. As a child, Alice''s close friendship with the writer was the creative catalyst for Carroll''s most beloved work. However, as Alice reflects on her experiences with the author, she slowly realises the complexity of their bond has had lasting, deeply felt ramifications.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.5139, "vote_average"=6.588, "is_ambiguous"=0, "evidence_score"=7.01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2377;
UPDATE "recommendations" SET "tmdb_id"=364, "imdb_id"='tt0103776', "igdb_id"=NULL, "title"='Batman Returns', "original_title"='Batman Returns', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/jKBjeXM7iBBV9UkUcOXx3m7FSHY.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7x4SNxO5HWArighxxFeet5sn3il.jpg', "overview"='The monstrous Penguin, who dwells in the sewers beneath Gotham, joins up with corrupt mayoral candidate Max Shreck to topple the Batman once and for all. But when Shreck''s timid assistant Selina Kyle finds out, and Shreck tries to kill her, she''s transformed into the sexy Catwoman. She teams up with the Penguin and Shreck to destroy Batman, but sparks fly unexpectedly when she confronts the caped crusader.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.3741, "vote_average"=6.949, "is_ambiguous"=0, "evidence_score"=8.45999999999999907e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2382;
UPDATE "recommendations" SET "tmdb_id"=453, "imdb_id"='tt0268978', "igdb_id"=NULL, "title"='A Beautiful Mind', "original_title"='A Beautiful Mind', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/rEIg5yJdNOt9fmX4P8gU9LeNoTQ.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hCJFWTPghXCwwSpvPpAoIB8318Q.jpg', "overview"='From the heights of notoriety to the depths of depravity, John Forbes Nash Jr. experiences it all. As a brilliant but socially awkward mathematician, he made a groundbreaking discovery early in his career and stands on the brink of international acclaim. But as the handsome and arrogant Nash accepts secret work in cryptography, he becomes entangled in a mysterious conspiracy. His life takes a nightmarish turn and he soon finds himself on a painful and harrowing journey of self-discovery.', "external_url"=NULL, "platforms"=NULL, "popularity"=14.7018, "vote_average"=7.853, "is_ambiguous"=0, "evidence_score"=1.23916666666666657e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2383;
UPDATE "recommendations" SET "tmdb_id"=8271, "imdb_id"='tt0486822', "igdb_id"=NULL, "title"='Disturbia', "original_title"='Disturbia', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/3f9KwSrieczuH9nRrwfOsoMoMNd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/ve38VxE3qVdk5xbEluWTqFa9oGd.jpg', "overview"='Kale has a life most teenagers would envy. He spends his days endlessly playing video games, surfing the net, eating junk food and watching cable. He has complete free reign of the house, and a beautiful young hottie named Ashley has just moved in next door. There’s only one problem—he’s not allowed to leave the house. Kale’s under court-ordered house arrest for three months, and if he takes one step beyond a 100-foot perimeter of the house, his next confinement will be in a real prison.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.4946, "vote_average"=6.69, "is_ambiguous"=0, "evidence_score"=34.2971875, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2386;
