UPDATE "recommendations" SET "tmdb_id"=49637, "imdb_id"='tt1396227', "igdb_id"=NULL, "title"='The Wild and Wonderful Whites of West Virginia', "original_title"='The Wild and Wonderful Whites of West Virginia', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/7EQQsuK1Hk1zcoBlNBKfU41aS39.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2S0Kk3cMPE2CX0vEJ6Fp5OjPZgI.jpg', "overview"='Produced by Johnny Knoxville and Jeff Tremaine for MTV and Dickhouse Productions, The Wild and Wonderful Whites of West Virginia is a documentary about the renowned West Virginia outlaw Jesco White and his eccentric backwoods family. In addition to getting in trouble with the law, the Whites, who live deep within Appalachia, uphold a time-honored dancing style, even as they contend with poverty, drugs and other issues. Alternately humorous and sad, the movie is an unflinching look at life on the criminal margins of rural mountain culture.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.7399, "vote_average"=6.74, "is_ambiguous"=0, "evidence_score"=14.016, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2575;
UPDATE "recommendations" SET "tmdb_id"=748853, "imdb_id"='tt13429362', "igdb_id"=NULL, "title"='In the Earth', "original_title"='In the Earth', "media_type"='movie', "release_year"=2021, "poster_url"='https://image.tmdb.org/t/p/w500/a2e9GLb14xX1DFv80nsioci5Zld.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fjRlDPqo2qqMBoUItMtTDZe9kvZ.jpg', "overview"='As a deadly virus ravages the world, Dr. Martin Lowery embarks on a mission to reach test site ATU327A, a research hub deep in the Arboreal Forest. The arduous journey, guided by park scout Alma, is set back by a nighttime attack that leaves the two bruised and shoeless. When they run into Zach, a man living off the grid, they gratefully accept his help. Zach’s intentions aren’t exactly what they seem, however, and a path out of the forest and into safety quickly fades as the line between myth and science blurs.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.0966, "vote_average"=5.597, "is_ambiguous"=0, "evidence_score"=8.5275, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2577;
UPDATE "recommendations" SET "tmdb_id"=24276, "imdb_id"='tt0093509', "igdb_id"=NULL, "title"='Matewan', "original_title"='Matewan', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/jMYqoM60clzYIQriM1wYXXBjU3O.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7Z2448JzjPf2THI0oJ0dsfSz56y.jpg', "overview"='Filmed in the coal country of West Virginia, "Matewan" celebrates labor organizing in the context of a 1920s work stoppage. Union organizer, Joe Kenehan, a scab named "Few Clothes" Johnson and a sympathetic mayor and police chief heroically fight the power represented by a coal company and Matewan''s vested interests so that justice and workers'' rights need not take a back seat to squalid working conditions, exploitation and the bottom line.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.6641, "vote_average"=7.342, "is_ambiguous"=0, "evidence_score"=15.40375, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-09 02:29:31' WHERE "id"=2578;
