UPDATE "recommendations" SET "tmdb_id"=358364, "imdb_id"='tt3315656', "igdb_id"=NULL, "title"='Split', "original_title"='Split', "media_type"='movie', "release_year"=2016, "poster_url"='https://image.tmdb.org/t/p/w500/8nn3m1wyu3woLg2tW1CAr44q53K.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/t4L7TKCUU57YhDS2gfWOWWDbwYH.jpg', "overview"='The story of a young woman who takes an epic journey to claim her own darkness and sexuality so she can stop putting it into the hands of her abusive lover.  When Inanna, a young actress, working as a stripper, becomes obsessed with a mask maker, she sacrifices parts of herself and her life, piece by piece, in order to win his love.  At the same time she enters a mythic journey in the theater.  One that forces her to face the many abuses endured by women around that world and that blurs her performance, her dreams and her real life and results in a provocative and powerful confrontation that frees her. -- from official website', "external_url"=NULL, "platforms"=NULL, "popularity"=1.507, "vote_average"=5.907, "is_ambiguous"=0, "evidence_score"=6.26, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-09 02:29:31' WHERE "id"=3815;
