UPDATE "recommendations" SET "tmdb_id"=1567187, "imdb_id"='tt33052885', "igdb_id"=NULL, "title"='A Mother''s Recall', "original_title"='Memoria de una madre', "media_type"='movie', "release_year"=2025, "poster_url"='https://image.tmdb.org/t/p/w500/vhfrAIIe9jHiuD9qjOhLwnEgLdb.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/v2SOWxOgifIhnZFLgIEvzr7ZbJ2.jpg', "overview"='A married couple welcomes young Genaro into their home through adoption. Upon his arrival, he meets his new siblings, Nuria and Samuel. But it doesn''t take long for Genaro to sense that something is deeply wrong within the household. The family seems trapped under a suffocating veil of fear and despair, haunted by an unseen force. As Nuria, a troubled teenager, begins to uncover the terrifying secrets hidden within her family, she forms a powerful bond with Genaro. Together, they must face an evil presence that grows stronger each day, unleashing a chain of sinister and unsettling events.', "external_url"=NULL, "platforms"=NULL, "popularity"=49.6735, "vote_average"=0.0, "is_ambiguous"=0, "evidence_score"=2.01, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-09 02:29:31' WHERE "id"=7338;
